const item = $input.first();
const body = item.json.body ?? {};

const reject = (code, reason) => [{
  json: { passed: false, rejectCode: code, rejectReason: reason, body },
}];

if (!body.candidateId) {
  return reject('missing_candidate', 'Missing candidate ID');
}

const transcript = String(body.fullTranscript || '').trim();
if (!transcript || transcript.length < 50) {
  return reject('invalid_transcript', 'Interview transcript is missing or too short');
}

const messageCount = Number(body.messageCount ?? 0);
if (messageCount < 2) {
  return reject('insufficient_messages', 'Interview must contain at least 2 messages');
}

if (body.criteria) {
  try {
    const criteria = typeof body.criteria === 'string' ? JSON.parse(body.criteria) : body.criteria;
    if (!Array.isArray(criteria) || criteria.length === 0) {
      throw new Error('empty criteria');
    }
  } catch {
    return reject('invalid_criteria', 'Criteria must be a valid non-empty JSON array');
  }
}

return [{
  json: { passed: true, rejectCode: '', rejectReason: '', body },
}];

const items = $input.all();
return items.map((item) => {
  const body = item.json.body ?? {};
  const callbackUrl = String(body.callbackUrl || '').trim();
  const inboundSecret = String(body.inboundSecret || '').trim();
  const candidateId = String(body.candidateId || '').trim();
  const inputValid = Boolean(callbackUrl && inboundSecret && candidateId);
  return {
    ...item,
    json: {
      ...item.json,
      __evaaloStageSecurity: {
        ...(item.json.__evaaloStageSecurity ?? {}),
        inputValid,
      },
    },
  };
});

const items = $input.all();
return items.map((item) => {
  const body = item.json.body ?? {};
  const callbackUrlRaw = String(body.callbackUrl || '').trim();

  const ALLOWED_ORIGINS = new Set([
    'https://api.evaalo.com',
    'http://100.73.82.78:5000',
    'http://localhost:5000',
    'http://127.0.0.1:5000',
  ]);
  const ALLOWED_PATHS = new Set([
    '/webhook/n8n/stage1',
    '/webhook/n8n/stage2',
    '/webhook/n8n/stage3',
    '/webhook/n8n/video',
  ]);
  const REQUIRED_QUERY_KEYS = ['candidateId', 'mode', 'sessionId', 'campaignId', 'issuedAt', 'expiresAt', 'token'];

  let urlValid = false;
  let urlRejectReason = '';
  if (callbackUrlRaw && !callbackUrlRaw.includes('@')) {
    const m = callbackUrlRaw.match(/^(https?):\/\/([^\/:?#]+)(?::(\d+))?(\/[^?#]*)?(?:\?([^#]*))?/i);
    if (m) {
      const protocol = m[1].toLowerCase();
      const host = m[2];
      const port = m[3] || '';
      const pathname = m[4] || '/';
      const query = m[5] || '';
      const origin = port ? `${protocol}://${host}:${port}` : `${protocol}://${host}`;
      if (!ALLOWED_ORIGINS.has(origin)) {
        urlRejectReason = 'origin';
      } else if (!ALLOWED_PATHS.has(pathname)) {
        urlRejectReason = 'path';
      } else {
        const params = {};
        for (const part of query.split('&')) {
          if (!part) continue;
          const eq = part.indexOf('=');
          const k = eq >= 0 ? decodeURIComponent(part.slice(0, eq)) : decodeURIComponent(part);
          const v = eq >= 0 ? decodeURIComponent(part.slice(eq + 1)) : '';
          params[k] = v;
        }
        const allKeys = REQUIRED_QUERY_KEYS.every((key) => {
          const val = String(params[key] ?? '').trim();
          return val !== '';
        });
        if (!allKeys) {
          urlRejectReason = 'query';
        } else if (params.mode !== 'stage3') {
          urlRejectReason = 'mode';
        } else {
          urlValid = true;
        }
      }
    } else {
      urlRejectReason = 'parse';
    }
  } else {
    urlRejectReason = 'empty';
  }

  return {
    ...item,
    json: {
      ...item.json,
      __evaaloStageSecurity: {
        ...(item.json.__evaaloStageSecurity ?? {}),
        urlValid,
        urlRejectReason,
      },
    },
  };
});

const sec = $json.__evaaloStageSecurity ?? {};
throw new Error(
  `INVALID_STAGE3_CALLBACK: inputValid=${sec.inputValid} urlValid=${sec.urlValid} reason=${sec.urlRejectReason || 'unknown'}`
);

const items = $input.all();
function parseJsonLoose(raw) {
  if (raw == null) return null;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return null;
  let s = raw.trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const m = s.match(/\{[\s\S]*\}/);
  if (m) s = m[0];
  try { return JSON.parse(s); } catch { return null; }
}
function targetLang() {
  const raw = String($('Webhook').first().json.body?.language || 'ar').trim().toLowerCase();
  if (raw === 'en' || raw.startsWith('en-')) return 'en';
  return 'ar';
}
function blueprintTitles() {
  const map = {};
  try {
    const comps = $('Webhook').first().json.body.blueprintSnapshot.competencies;
    if (Array.isArray(comps)) {
      for (const c of comps) {
        const k = c && c.competencyKey;
        const title = String((c && c.title) || '').trim();
        if (k && title) map[k] = title;
      }
    }
  } catch (e) {}
  return map;
}
function finalize(r) {
  const out = { ...r };
  // Carry the blueprint's own competency titles through, so the UI shows the
  // role's wording (already in the campaign language) instead of a snake_case key.
  const titles = blueprintTitles();
  if (Array.isArray(out.competencyScores)) {
    out.competencyScores = out.competencyScores.map((c) => {
      const title = c && titles[c.competencyKey];
      return title ? { ...c, title } : c;
    });
  }
  // Coverage gate: an interview that did not cover enough of the role must not
  // report a passing percentage. The scorer still computes one, and showing it
  // beside "insufficient data" reads as a real pass mark.
  if (String(out.status || '').trim().toLowerCase() === 'insufficient_data') {
    out.overall_score = 0;
    out.recommendation = 'Reject';
  }
  return out;
}
return items.map((item) => {
  const original = $('Stage 3 Scoring').first().json ?? {};
  if (targetLang() === 'en') { return { json: finalize(original) }; }
  let o = parseJsonLoose(item.json.output ?? item.json.text ?? item.json);
  if (o && o.output && typeof o.output === 'object') o = o.output;
  const t = (o && typeof o === 'object') ? o : {};
  const merged = { ...original, ...t };
  merged.overall_score = original.overall_score;
  merged.recommendation = original.recommendation;
  merged.status = original.status;
  merged.blueprint_coverage = original.blueprint_coverage;
  merged.generic_ratings = original.generic_ratings;
  merged.red_flags_fired = original.red_flags_fired;
  merged.critical_concerns = original.critical_concerns;
  if (Array.isArray(original.competencyScores)) {
    const to = Array.isArray(merged.competencyScores) ? merged.competencyScores : [];
    merged.competencyScores = original.competencyScores.map((oc, i) => {
      const tc = to[i] || {};
      return { competencyKey: oc.competencyKey, score: oc.score, assessed: oc.assessed, evidence: Array.isArray(tc.evidence) ? tc.evidence : oc.evidence, redFlags: oc.redFlags };
    });
  }
  return { json: finalize(merged) };
});

