const CLUSTER = { blueprint: 65, role_judgment_problem_solving: 15, ownership_accountability: 8, learning_adaptability: 7, overall_role_fit: 5 };
const GENERIC_KEYS = ['role_judgment_problem_solving', 'ownership_accountability', 'learning_adaptability', 'overall_role_fit'];
const RATING_FRACTION = { excellent: 1.0, good: 0.75, intermediate: 0.5, bad: 0.0 };
const PRIORITY_WEIGHT = { critical: 3, high: 2, medium: 1 };
const BLUEPRINT_COVERAGE_FLOOR = 0.5;
const SOFT_REDFLAG_CAP = 0.5;
const STAR_CAP = 0.75;
const T_HIRE = 70;
const T_CONSIDER = 49;
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }
function titleCase(s) { const x = norm(s); return x ? x.charAt(0).toUpperCase() + x.slice(1) : x; }
function isNA(v) { const x = norm(v); return x === '' || x === 'not assessed' || x === 'n/a' || x === 'na' || x === 'none'; }
function txt(v) { return String(v == null ? '' : v).trim(); }
function rubricFraction(score) { const n = Number(score); if (!Number.isFinite(n)) return null; const c = Math.max(1, Math.min(5, n)); return (c - 1) / 4; }
function toArray(v) { if (Array.isArray(v)) return v.filter((x) => txt(x)); const s = txt(v); return s ? [s] : []; }
function getAssessment(item) { const j = item.json || {}; if (j.output && typeof j.output === 'object') return j.output; if (j.blueprint || j.generic) return j; const raw = j.text || j.response || j.data || ''; const m = String(raw).match(/\{[\s\S]*\}/); if (m) { try { return JSON.parse(m[0]); } catch (e) {} } return {}; }
function getBlueprintDef(item) { let comps = []; try { const c = $('Webhook').first().json.body.blueprintSnapshot.competencies; if (Array.isArray(c)) comps = c; } catch (e) {} if (!comps.length && item.json && item.json.__blueprint) comps = item.json.__blueprint; const map = {}; for (const c of comps) { map[c.competencyKey] = { priority: norm(c.priority) || 'high', title: txt(c.title), redFlags: (Array.isArray(c.redFlags) ? c.redFlags : []).map((r) => norm(r)).filter(Boolean) }; } return map; }
function whitelistRedFlags(detected, predefined) { const out = []; for (const d of (Array.isArray(detected) ? detected : [])) { const flag = norm(d && (d.flag != null ? d.flag : d)); const quote = txt(d && d.quote); if (!flag || !quote) continue; if (predefined.some((p) => p && (p.includes(flag) || flag.includes(p)))) out.push({ flag, quote }); } return out; }
const out = [];
for (const item of $input.all()) {
  const a = getAssessment(item);
  const def = getBlueprintDef(item);
  const bpItems = Array.isArray(a.blueprint) ? a.blueprint : [];
  let totalBpWeight = 0, assessedBpWeight = 0, bpEarnedNorm = 0;
  let criticalMissing = false;
  const competencyScores = [];
  const flagsFired = [];
  const allKeys = new Set([...Object.keys(def), ...bpItems.map((b) => b && b.competencyKey).filter(Boolean)]);
  for (const k of allKeys) totalBpWeight += PRIORITY_WEIGHT[(def[k] && def[k].priority) || 'high'] || 2;
  const assessed = [];
  const seen = new Set();
  for (const b of bpItems) {
    const key = b && b.competencyKey; if (!key) continue;
    seen.add(key);
    const d = def[key] || { priority: 'high', redFlags: [] };
    const pW = PRIORITY_WEIGHT[d.priority] || 2;
    const notAssessed = b.assessed === false || isNA(b.score) || rubricFraction(b.score) === null;
    if (notAssessed) { if (d.priority === 'critical') criticalMissing = true; competencyScores.push({ competencyKey: key, title: d.title, score: null, assessed: false, evidence: [], redFlags: [] }); continue; }
    let frac = rubricFraction(b.score);
    const ev = b.evidence || {};
    const hasAR = txt(ev.action) && txt(ev.result);
    if (Number(b.score) >= 5 && !hasAR) frac = Math.min(frac, STAR_CAP);
    const rf = whitelistRedFlags(b.redFlagsDetected, d.redFlags);
    if (rf.length) { frac = Math.min(frac, SOFT_REDFLAG_CAP); flagsFired.push({ competencyKey: key, redFlags: rf.map((x) => x.flag) }); }
    assessed.push({ key, pW, frac });
    assessedBpWeight += pW;
    competencyScores.push({ competencyKey: key, title: d.title, score: Number(b.score), assessed: true, evidence: [ev.claim, ev.situation, ev.action, ev.result, ev.quote].filter((x) => txt(x)), redFlags: rf.map((x) => x.flag) });
  }
  // A competency the assessor never returned is still part of the role, so it has
  // to show up as not assessed rather than silently vanish from the report.
  for (const k of Object.keys(def)) {
    if (seen.has(k)) continue;
    if (def[k].priority === 'critical') criticalMissing = true;
    competencyScores.push({ competencyKey: k, title: def[k].title, score: null, assessed: false, evidence: [], redFlags: [] });
  }
  // Unassessed competencies still count toward the role: distribute the blueprint
  // cluster across ALL competencies (totalBpWeight), so a competency the candidate
  // dodged earns 0 and dilutes the score instead of being silently dropped.
  for (const c of assessed) { const share = totalBpWeight > 0 ? CLUSTER.blueprint * (c.pW / totalBpWeight) : 0; bpEarnedNorm += share * c.frac; }
  const bpMaxAssessed = assessed.length ? CLUSTER.blueprint : 0;
  const gen = a.generic || {};
  let genEarned = 0, genMaxAssessed = 0;
  const genRatings = {};
  for (const k of GENERIC_KEYS) { const nd = gen[k] || {}; const r = nd.assessed === false ? 'Not Assessed' : nd.rating; if (isNA(r) || !(norm(r) in RATING_FRACTION)) { genRatings[k] = 'Not Assessed'; continue; } genEarned += RATING_FRACTION[norm(r)] * CLUSTER[k]; genMaxAssessed += CLUSTER[k]; genRatings[k] = titleCase(r); }
  const criticalConcerns = (Array.isArray(a.critical_concerns) ? a.critical_concerns : []).filter((c) => txt(c && c.concern) && txt(c && c.quote));
  const coverage = totalBpWeight > 0 ? assessedBpWeight / totalBpWeight : 0;
  let status = 'scored';
  let score = null;
  const denom = bpMaxAssessed + genMaxAssessed;
  if (denom > 0) score = Math.round(((bpEarnedNorm + genEarned) / denom) * 100);
  if (bpMaxAssessed === 0) { status = 'insufficient_data'; }
  let recommendation;
  if (status === 'insufficient_data') {
    // Too little of the role was covered to stand behind any number. Reporting a
    // percentage next to "insufficient data" reads as a pass mark it never earned.
    recommendation = 'Reject';
    score = 0;
  } else { recommendation = score >= T_HIRE ? 'Hire' : score >= T_CONSIDER ? 'Consider' : 'Reject'; }
  if (criticalConcerns.length) { status = status === 'insufficient_data' ? status : 'manual_review'; if (recommendation === 'Hire') recommendation = 'Consider'; }
  let finalHr = txt(a.overall_role_fit_narrative);
  let summary = txt(a.summary);
  const notes = [];
  if (status === 'insufficient_data') notes.push('No competencies could be assessed from this interview -- no score is reported and the outcome is Reject; recommend re-interview or manual review.');
  if (assessed.length && assessed.length < allKeys.size) notes.push('Some role competencies were not evidenced in the interview and are counted as unmet in the score.');
  if (criticalConcerns.length) notes.push('Critical concern flagged (' + criticalConcerns.map((c) => txt(c.concern)).join('; ') + ') -- mandatory human review before any hire decision.');
  if (notes.length) { const n = 'NOTE: ' + notes.join(' '); finalHr = finalHr ? (finalHr + '\n\n' + n) : n; summary = summary ? (summary + '\n\n' + n) : n; }
  out.push({ json: { overall_score: score, recommendation, status, blueprint_coverage: Math.round(coverage * 100) / 100, competencyScores, red_flags_fired: flagsFired, critical_concerns: criticalConcerns, generic_ratings: genRatings, summary, strengths: toArray(a.strengths), weaknesses: toArray(a.weaknesses), final_hr_evaluation: finalHr } });
}
return out;

const r = $input.first().json || {};
const body = $('Webhook').first().json.body || {};
const str = (v) => (v == null ? '' : String(v).trim());
const jarr = (v) => Array.isArray(v) ? JSON.stringify(v) : (v == null ? '[]' : JSON.stringify([v]));
const jobj = (v) => (v && typeof v === 'object') ? JSON.stringify(v) : str(v);
const numv = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const candidateId = str(body.candidateId || r.CandidateID);
if (!candidateId) return [];
const scoreNum = numv(r.overall_score);
const applicantName = str(body.full_name || body.fullName || body.candidateName) || ('Candidate ' + candidateId.slice(-6));
return [{ json: {
  CandidateID: candidateId,
  CampaignID: str(body.campaignId || body.campaignID),
  SessionID: str(body.sessionId),
  Language: str(body.language) || 'ar',
  ApplicantName: applicantName,
  Summary: str(r.summary),
  Strengths: jarr(r.strengths),
  Weaknesses: jarr(r.weaknesses),
  FinalHREvaluation: str(r.final_hr_evaluation),
  Recommendation: str(r.recommendation),
  OverallScore: String(scoreNum),
  OverallScoreNumeric: scoreNum,
  Status: str(r.status),
  BlueprintCoverage: jobj(r.blueprint_coverage),
  CompetencyScores: jarr(r.competencyScores),
  GenericRatings: jobj(r.generic_ratings),
  RedFlagsFired: jarr(r.red_flags_fired),
  CriticalConcerns: jarr(r.critical_concerns),
  EvaluatedAt: new Date().toISOString(),
  Ingress: 'stage3',
} }];
